INSERT INTO `chatbot_faqs` VALUES (1,'What are market hours?','Most markets run 8:00 to 13:00 on their listed days. Open a market page for the exact schedule.','hours','[\"hours\",\"time\",\"open\",\"timing\"]','2026-09-26 16:26:46','2026-09-26 16:26:46'),(2,'How do I pre-order?','Add products to your cart, choose a pickup date and slot, and place the order before cutoff. You pay the farmer in person.','orders','[\"order\",\"pre-order\",\"cart\",\"checkout\"]','2026-09-26 16:26:46','2026-09-26 16:26:46'),(3,'When is pickup?','Pickup is during the slot you chose, at the market attached to each product.','pickup','[\"pickup\",\"collect\",\"slot\",\"window\"]','2026-09-26 16:26:46','2026-09-26 16:26:46'),(4,'Can I cancel?','You can change or cancel a pre-order until the cutoff time shown on the order.','orders','[\"cancel\",\"change\",\"cutoff\"]','2026-09-26 16:26:46','2026-09-26 16:26:46'),(5,'Do you deliver?','No. MarketLink is pickup only. There is no courier and no online payment.','pickup','[\"delivery\",\"pay\",\"payment\"]','2026-09-26 16:26:46','2026-09-26 16:26:46');
/*!40000 ALTER TABLE `chatbot_faqs` ENABLE KEYS */;
