INSERT INTO `smart_crops` VALUES (1,'tomato','Tomato','ٹماٹر','🍅','vegetable',1,1,15.0,30.0,40,75,1,'{\"water\":{\"amount\":\"25\\u201340 mm\\/week (more in heat)\",\"frequency\":\"Every 2\\u20133 days; keep soil evenly moist\",\"best_time\":\"Early morning\",\"warning\":\"Avoid waterlogging \\u2014 root rot and fruit crack\"},\"soil\":{\"type\":\"Loamy, well-drained, rich organic matter\",\"requirements\":\"pH 6.0\\u20136.8; compost before transplant\"},\"temperature\":{\"range\":\"18\\u201327\\u00b0C ideal\",\"warning\":\"Above 35\\u00b0C flower drop; below 10\\u00b0C slow growth\"},\"growth\":{\"period\":\"70\\u201390 days from transplant\",\"harvest\":\"First pick ~75 days; harvest every 3\\u20135 days\",\"care\":\"Stake plants, prune suckers, mulch beds\"},\"problems\":{\"pests\":\"Aphids, whitefly, fruit borer\",\"diseases\":\"Early\\/late blight, wilt, leaf curl\",\"prevention\":\"Rotate crops, remove infected leaves, avoid wet foliage overnight\"}}','{\"water\":{\"amount\":\"\\u06c1\\u0641\\u062a\\u06c1 \\u0648\\u0627\\u0631 25\\u201340 \\u0645\\u0644\\u06cc \\u0645\\u06cc\\u0679\\u0631 (\\u06af\\u0631\\u0645\\u06cc \\u0645\\u06cc\\u06ba \\u0632\\u06cc\\u0627\\u062f\\u06c1)\",\"frequency\":\"\\u06c1\\u0631 2\\u20133 \\u062f\\u0646\\u061b \\u0645\\u0679\\u06cc \\u06cc\\u06a9\\u0633\\u0627\\u06ba \\u0646\\u0645 \\u0631\\u06a9\\u06be\\u06cc\\u06ba\",\"best_time\":\"\\u0635\\u0628\\u062d \\u062c\\u0644\\u062f\\u06cc\",\"warning\":\"\\u06a9\\u06be\\u0691\\u0627 \\u067e\\u0627\\u0646\\u06cc \\u0646\\u06c1 \\u0631\\u06c1\\u0646\\u06d2 \\u062f\\u06cc\\u06ba \\u2014 \\u062c\\u0691 \\u0633\\u0691\\u0646 \\u0627\\u0648\\u0631 \\u067e\\u06be\\u0644 \\u067e\\u06be\\u0679 \\u0633\\u06a9\\u062a\\u06d2 \\u06c1\\u06cc\\u06ba\"},\"soil\":{\"type\":\"\\u0686\\u06a9\\u0646\\u0627\\u0626\\u06cc \\u0648\\u0627\\u0644\\u06cc\\u060c \\u0627\\u0686\\u06be\\u06cc \\u0646\\u06a9\\u0627\\u0633\\u06cc \\u0648\\u0627\\u0644\\u06cc \\u0645\\u0679\\u06cc\",\"requirements\":\"pH 6.0\\u20136